"""Captured real FR trainer evidence; independent decode, no emulator."""
from tests.unit.test_patch_rival_live import rival_problems

CAPTURE = 'HELPER: [gen3] phase field frame=731 map=(1,0)\nTRAINER_READY x=41 y=45 lock=0 script=2\nTRAINER_STEP x=42 y=45 lock=1 script=1 trainer=102\nWINDOW_POST callback=08010509 main=080123BD stage=0 trainer=102 flags=8\nORIGINAL_ENEMY \nRIVAL_CONSUME seq=1 callback=08010509 main=080123BD stage=0 flags=8 trainer=102 inbattle=1 sp=03007DF4\nRIVAL_ACK seq=1 status=2 reason=0\nSELECTION_ENTRY count=2 ack=1 status=2 stage=15\nSELECTION_PARTY \nBATTLE_SNAPSHOT index=1 count=2 mon=100008000700090008000800210000000000000068C8430D060606060606060633000204230000001100045411000000BBBBBBBBBBBBBBBBBBBBFF00C4C9C8C8BCFFFFFF78000000B6203626000000000000000075F22166\nRIVAL_CONSUME seq=2 callback=08011101 main=08014041 stage=1 flags=C trainer=102 inbattle=1 sp=03007DF4\nLATE_BEFORE \nLATE_AFTER \nLATE_REFUSED status=3 reason=8 count=2 unchanged=1 consumes=2\nRIVAL_SCOPE: real Rick102 battle, replayed peer team with fainted lead; no live server/duo or save claim\nSCOPE: FR native Rival W1/late refusal on real Rick102 battle; replayed team, no server/duo qualification\nRESULT: PASS \n'
PAYLOAD = bytes.fromhex('')

def test_real_trainer_capture_and_negative_controls():
    assert not rival_problems(CAPTURE,PAYLOAD)
    for old,new in (("BATTLE_SNAPSHOT index=1","BATTLE_SNAPSHOT index=0"),
                    ("SELECTION_ENTRY count=2 ack=1","SELECTION_ENTRY count=2 ack=0"),
                    ("RIVAL_ACK seq=1 status=2","RIVAL_ACK seq=1 status=3"),
                    ("LATE_REFUSED status=3 reason=8","LATE_REFUSED status=2 reason=0"),
                    ("RIVAL_CONSUME seq=1 callback=08010509","RIVAL_CONSUME seq=1 callback=08011101"),
                    ("LATE_AFTER 90","LATE_AFTER 91")):
        assert rival_problems(CAPTURE.replace(old,new),PAYLOAD)
